bad = []
for rel, (old, new, _data) in MOD.items():
    f = ROOT / rel
    if not f.exists():
        bad.append(f"{rel} (missing)")
    elif norm_sha(f.read_bytes()) not in (old, new):
        bad.append(f"{rel} (content differs from develop@4ca1789)")
if bad:
    print("ABORT - nothing was changed. Problem files:")
    for b in bad:
        print("  ", b)
    sys.exit(1)

backup = ROOT / "p112_backups" / ("step2_" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))
for rel, (old, new, data) in sorted(MOD.items()):
    f = ROOT / rel
    if norm_sha(f.read_bytes()) == new:
        print("  unchanged", rel)
        continue
    (backup / rel).parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(f, backup / rel)
    f.write_bytes(dec(data))
    print("  edited   ", rel)
for rel, data in sorted(NEW.items()):
    f = ROOT / rel
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_bytes(dec(data))
    print("  wrote    ", rel)
print("\nDone. Next: python -m core.i18n_tools")